   where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any (array['accounting_baselines','affinaj_records','audit_log','audit_logs','batch_images','batch_models','batch_operations','batch_stage_wip','batch_status_history','batches','bom_items','client_gold_accounts','client_legacy_debts','company_rate_differences','consignment_pieces','consumption','customers','daily_gold_rates','debt_repayments','departments','employees','factory_gold_handovers','factory_receipts','financial_transactions','gold_lots','gold_purchases','gold_settlements','gold_transactions','idempotency_keys','inventory_categories','inventory_items','inventory_reservations','inventory_transactions','jewelry_model_images','jewelry_models','jewelry_sales','machines','manager_vault_account','order_items','orders','organization_factory_settings','organizations','production_stages','products','qc_checklist_items','qc_checklists','qc_inspection_results','qc_inspections','quality_control','refining_batches','salary_ledger','sales','sales_login_audit_logs','sales_markup_presets','seller_consignments','seller_gold_accounts','seller_rate_history','seller_rate_limits','seller_rates','sheets_import_batches','stage_loss_configs','staging_backup_snapshots','system_settings','two_party_handovers','weight_sale_allocations','workflow_stages']::text[]) group by c.relname
), diff as (
            select 'function missing: ' || e.sig d from exp_f e where not exists (select 1 from act_f a where a.sig = e.sig)
  union all select 'function extra overload: ' || a.sig from act_f a where not exists (select 1 from exp_f e where e.sig = a.sig)
  union all select 'function body/attributes differ: ' || e.sig from exp_f e join act_f a using (sig) where a.fp <> e.fp
  union all select 'function grants differ: ' || e.sig || ' expected [' || e.acl || '] got [' || a.acl || ']' from exp_f e join act_f a using (sig) where a.acl <> e.acl
  union all select 'policy missing: ' || e.t || '.' || e.n from exp_p e where not exists (select 1 from act_p a where a.t = e.t and a.n = e.n)
  union all select 'policy extra: ' || a.t || '.' || a.n from act_p a where not exists (select 1 from exp_p e where e.t = a.t and e.n = a.n)
  union all select 'policy differs: ' || e.t || '.' || e.n from exp_p e join act_p a on a.t = e.t and a.n = e.n where (a.cmd, a.perm, a.roles) is distinct from (e.cmd, e.perm, e.roles)
  union all select 'table missing: ' || e.t from exp_c e where not exists (select 1 from act_c a where a.t = e.t)
  union all select 'columns differ: ' || e.t from exp_c e join act_c a using (t) where a.c <> e.c
  union all select 'RLS disabled: ' || x from unnest(array['accounting_baselines','affinaj_records','audit_log','audit_logs','batch_images','batch_models','batch_operations','batch_stage_wip','batch_status_history','batches','bom_items','client_gold_accounts','client_legacy_debts','company_rate_differences','consignment_pieces','consumption','customers','daily_gold_rates','debt_repayments','departments','employees','factory_gold_handovers','factory_receipts','financial_transactions','gold_lots','gold_purchases','gold_settlements','gold_transactions','idempotency_keys','inventory_categories','inventory_items','inventory_reservations','inventory_transactions','jewelry_model_images','jewelry_models','jewelry_sales','machines','manager_vault_account','order_items','orders','organization_factory_settings','organizations','production_stages','products','qc_checklist_items','qc_checklists','qc_inspection_results','qc_inspections','quality_control','refining_batches','salary_ledger','sales','sales_login_audit_logs','sales_markup_presets','seller_consignments','seller_gold_accounts','seller_rate_history','seller_rate_limits','seller_rates','sheets_import_batches','stage_loss_configs','staging_backup_snapshots','system_settings','two_party_handovers','weight_sale_allocations','workflow_stages']::text[]) x
     where not exists (select 1 from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname = x and c.relrowsecurity)
)
select case when count(*) = 0 then 'PASS' else 'FAIL' end as parity, count(*) as differences, string_agg(d, E'
' order by d) as details from diff;
rollback;
